from collections import deque
import heapq

tree = {"S": ["A", "B"], "A": ["C"], "B": ["G2"], "C": ["G1"], "G1": [], "G2": []}
goals = {"G1", "G2"}

def bfs():
    q = deque(["S"])
    order = []
    while q:
        n = q.popleft()
        order.append(n)
        if n in goals:
            return order, n
        q.extend(tree[n])

def dfs():
    stack = ["S"]
    seen = set()
    order = []
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        order.append(n)
        if n in goals:
            return order, n
        stack.extend(reversed(tree[n]))

def dls(limit):
    stack = [("S", 0)]
    order = []
    while stack:
        n, d = stack.pop()
        order.append(n)
        if n in goals:
            return order, n
        if d == limit:
            continue
        stack.extend((c, d + 1) for c in reversed(tree[n]))
    return order, None

bo, bg = bfs()
do, dg = dfs()
assert bo == ["S", "A", "B", "C", "G2"] and bg == "G2"
assert do == ["S", "A", "C", "G1"] and dg == "G1"
total = sum(len(dls(limit)[0]) for limit in range(3))
assert total == 9 and dls(2)[1] == "G2"
graph = {"S": [("A", 1), ("B", 2)], "A": [("G", 3)], "B": [("G", 1)], "G": []}
pq = [(0, "S")]
best = {"S": 0}
first_gen = None
final = None
while pq:
    g, n = heapq.heappop(pq)
    if g != best.get(n, 10**9):
        continue
    if n == "G":
        final = g
        break
    for m, c in graph[n]:
        ng = g + c
        if m == "G" and first_gen is None:
            first_gen = ng
        if ng < best.get(m, 10**9):
            best[m] = ng
            heapq.heappush(pq, (ng, m))
assert final == 3 and first_gen == 4
assert 1 + 3 + 9 == 13
print(bg, dg, total, final)
